class Starship {
  #shieldStrength;

  constructor(name, initialShield) {
    this.name = name;
    this.#shieldStrength = initialShield;
  }

  activateShields(boostAmount) {
    this.#shieldStrength = Math.min(100, this.#shieldStrength + boostAmount);
  }

  takeDamage(damageAmount) {
    this.#shieldStrength = Math.max(0, this.#shieldStrength - damageAmount);
  }

  getShieldStatus() {
    return this.#shieldStrength;
  }
}

